228: class BIE_CopyCellData : BoundaryInterfaceEffect {
229:     this(int id, int boundary, double Twall=300.0)
230:     {
231:         super(id, boundary, "CopyCellData");
232:     }
233: 
234:     override string toString() const
235:     {
236:         return "CopyCellData()";
237:     }
238: 
239:     override void apply_for_interface_unstructured_grid(double t, int gtl, int ftl, FVInterface f)
240:     {
241:         BoundaryCondition bc = blk.bc[which_boundary];
242: 	if (bc.outsigns[f.i_bndry] == 1) {
243: 	    f.fs.copy_values_from(f.left_cell.fs);
244: 	} else {
245: 	    f.fs.copy_values_from(f.right_cell.fs);
246: 	}
247:     }
248: 
249:     override void apply_unstructured_grid(double t, int gtl, int ftl)
250:     {
251:         BoundaryCondition bc = blk.bc[which_boundary];
252:         foreach (i, f; bc.faces) {
253:             auto c = (bc.outsigns[i] == 1) ? f.left_cell : f.right_cell;
254:             f.fs.copy_values_from(c.fs);
255:         }
256:     }
257: 
258:     override void apply_for_interface_structured_grid(double t, int gtl, int ftl, FVInterface f)
259:     {
260:         auto gmodel = blk.myConfig.gmodel;
261:         auto blk = cast(SFluidBlock) this.blk;
262:         assert(blk !is null, "Oops, this should be an SFluidBlock object.");
263:         BoundaryCondition bc = blk.bc[which_boundary];
264:         auto c = (bc.outsigns[f.i_bndry] == 1) ? f.left_cells[0] : f.right_cells[0];
265:         f.fs.copy_values_from(c.fs);
266:     }
267: 
268:     override void apply_structured_grid(double t, int gtl, int ftl)
269:     {
270:         auto gmodel = blk.myConfig.gmodel;
271:         auto blk = cast(SFluidBlock) this.blk;
272:         assert(blk !is null, "Oops, this should be an SFluidBlock object.");
273:         BoundaryCondition bc = blk.bc[which_boundary];
274:         foreach (i, f; bc.faces) {
275:             auto c = (bc.outsigns[i] == 1) ? f.left_cells[0] : f.right_cells[0];
276:             f.fs.copy_values_from(c.fs);
277:         }
278:     } // end apply_structured_grid()
279: } // end class BIE_CopyCellData

